package ai.codeandcraft.secondbrain;
import android.content.Context;import android.os.SystemClock;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.text.BreakIterator;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;
/** Exact lexical excerpts only. No semantic decisions, action attribution or generative summary. */
public final class EvidenceExcerptBaseline {
    private EvidenceExcerptBaseline(){}
    private static final class Stop extends Exception{final String status;Stop(String s,String m){super(m);status=s;}}
    private static final class Guard{final long deadline;final AtomicBoolean cancel;Guard(long ms,AtomicBoolean c){deadline=SystemClock.elapsedRealtime()+ms;cancel=c;}void check()throws Stop{if(Thread.currentThread().isInterrupted()||(cancel!=null&&cancel.get()))throw new Stop("CANCELLED","No output committed");if(SystemClock.elapsedRealtime()>=deadline)throw new Stop("TIMEOUT","Time budget reached; no output committed");}}
    private static JSONObject empty(String status,String detail)throws Exception{return new JSONObject().put("schemaVersion",1).put("engine","lexical-graph-extractive-v1").put("label","Evidence excerpts — extractive, not a generative summary").put("status",status).put("detail",detail).put("excerpts",new JSONArray()).put("evidenceCorpus",new JSONArray()).put("actions",new JSONArray()).put("decisions",new JSONArray()).put("owner",JSONObject.NULL).put("dueDate",JSONObject.NULL).put("semanticFieldsStatus","NOT_EVALUATED").put("contradictionsStatus","NOT_EVALUATED").put("claimsVerified",false).put("persistentWrites",false);}
    private static void require(boolean ok,String status,String message)throws Stop{if(!ok)throw new Stop(status,message);}
    private static String sha(File file,Guard guard)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){guard.check();digest.update(b,0,n);}}StringBuilder out=new StringBuilder();for(byte b:digest.digest())out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
    private static JSONObject metadata(File file)throws Exception{require(file.isFile()&&file.length()<=262144,"NO_EVIDENCE","Missing/oversized session metadata");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(file)){byte[] b=new byte[4096];int n,total=0;while((n=in.read(b))!=-1){total+=n;require(total<=262144,"RESOURCE_LIMIT","Session metadata limit");out.write(b,0,n);}}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}
    private static final class Sentence{String quote;JSONObject anchor;int start,end,order;Set<String> words;double score;}
    private static Set<String> words(String text){HashSet<String> result=new HashSet<>();StringBuilder word=new StringBuilder();for(int i=0;i<=text.length();i++){char c=i<text.length()?text.charAt(i):' ';if(Character.isLetterOrDigit(c))word.append(Character.toLowerCase(c));else if(word.length()>0){result.add(word.toString());word.setLength(0);}}return result;}
    public static synchronized JSONObject build(Context context,File meeting,int maxExcerpts,long timeBudgetMs,AtomicBoolean cancel)throws Exception{
        long begin=SystemClock.elapsedRealtime();Guard guard=new Guard(Math.max(1,Math.min(5000,timeBudgetMs)),cancel);
        try{guard.check();require(maxExcerpts>=1&&maxExcerpts<=8&&timeBudgetMs>=1&&timeBudgetMs<=5000,"RESOURCE_LIMIT","Choose1–8 excerpts and1–5000ms");require(!RecorderService.isRecording(),"RECORDING_ACTIVE","Finish recording first");JSONArray chunks=metadata(new File(meeting,"session.json")).optJSONArray("chunks");require(chunks!=null&&chunks.length()>0,"NO_EVIDENCE","No completed audio chunks");require(chunks.length()<=32,"RESOURCE_LIMIT","Baseline supports at most32 source chunks");
            JSONObject job=WindowedTranscription.inspect(context,meeting,64);guard.check();require(job!=null,"NO_EVIDENCE","No verified transcription job");require(!job.optBoolean("boundaryReviewRequired"),"BOUNDARY_REVIEW_REQUIRED","Resolve overlapping transcript boundaries before extraction");require("COMPLETED".equals(job.optString("status")),"INCOMPLETE_TRANSCRIPT","Complete or resume the local transcription job");JSONArray outputs=job.getJSONArray("windows");require(outputs.length()<=64,"RESOURCE_LIMIT","Baseline supports at most64 transcript windows");
            File jobs=new File(meeting,"transcription-jobs").getCanonicalFile(),directory=new File(jobs,job.getString("jobId")).getCanonicalFile();require(jobs.equals(directory.getParentFile()),"INVALID_EVIDENCE","Escaping job directory");JSONArray corpus=new JSONArray();ArrayList<Sentence> sentences=new ArrayList<>();int chars=0;
            for(int i=0;i<outputs.length();i++){guard.check();JSONObject output=outputs.getJSONObject(i),window=output.getJSONObject("window");File truth=new File(directory,output.getString("truthDirectory")).getCanonicalFile();require(directory.equals(truth.getParentFile()),"INVALID_EVIDENCE","Escaping raw record");JSONObject record=TranscriptTruthStore.load(truth);guard.check();String text=record.getJSONObject("asr").getString("text");require(text.equals(output.getString("text")),"INVALID_EVIDENCE","Raw recognition text mismatch");chars+=text.length();require(chars<=16000,"RESOURCE_LIMIT","Raw transcript exceeds16000 characters");
                JSONObject anchor=new JSONObject().put("jobId",job.getString("jobId")).put("truthDirectory",truth.getName()).put("recordSha256",sha(new File(truth,"record.json"),guard)).put("sliceSha256",record.getJSONObject("source").getString("sha256")).put("window",new JSONObject(window.toString())).put("rangeMeaning","Original audio window; character offsets are text positions, not word audio timestamps");
                corpus.put(new JSONObject().put("rawText",text).put("anchor",anchor));BreakIterator iterator=BreakIterator.getSentenceInstance(Locale.ENGLISH);iterator.setText(text);int start=iterator.first();for(int end=iterator.next();end!=BreakIterator.DONE;start=end,end=iterator.next()){guard.check();int a=start,b=end;while(a<b&&Character.isWhitespace(text.charAt(a)))a++;while(b>a&&Character.isWhitespace(text.charAt(b-1)))b--;if(a==b)continue;require(b-a<=1000&&sentences.size()<128,"RESOURCE_LIMIT","Sentence/excerpt input limit reached");Sentence sentence=new Sentence();sentence.quote=text.substring(a,b);sentence.anchor=anchor;sentence.start=a;sentence.end=b;sentence.order=sentences.size();sentence.words=words(sentence.quote);sentences.add(sentence);}
            }
            require(!sentences.isEmpty(),"NO_SPEECH","Verified transcript has no non-empty text");int size=sentences.size();double[][] weights=new double[size][size];double[] sums=new double[size];
            for(int i=0;i<size;i++)for(int j=i+1;j<size;j++){guard.check();int overlap=0;for(String word:sentences.get(i).words)if(sentences.get(j).words.contains(word))overlap++;double denom=Math.sqrt((double)sentences.get(i).words.size()*sentences.get(j).words.size());double value=denom==0?0:overlap/denom;weights[i][j]=weights[j][i]=value;sums[i]+=value;sums[j]+=value;}
            double[] scores=new double[size];Arrays.fill(scores,1.0/size);for(int iteration=0;iteration<20;iteration++){guard.check();double[] next=new double[size];double dangling=0;for(int j=0;j<size;j++)if(sums[j]==0)dangling+=scores[j];for(int i=0;i<size;i++){guard.check();double sum=dangling/size;for(int j=0;j<size;j++)if(sums[j]>0)sum+=scores[j]*weights[j][i]/sums[j];next[i]=0.15/size+0.85*sum;}scores=next;}
            for(int i=0;i<size;i++)sentences.get(i).score=scores[i];ArrayList<Sentence> selected=new ArrayList<>(sentences);selected.sort((a,b)->{int cmp=Double.compare(b.score,a.score);return cmp==0?Integer.compare(a.order,b.order):cmp;});if(selected.size()>maxExcerpts)selected=new ArrayList<>(selected.subList(0,maxExcerpts));selected.sort(Comparator.comparingInt(s->s.order));JSONArray excerpts=new JSONArray();for(Sentence s:selected){guard.check();excerpts.put(new JSONObject().put("quote",s.quote).put("rawTextCharStart",s.start).put("rawTextCharEnd",s.end).put("anchor",new JSONObject(s.anchor.toString())).put("lexicalRankScore",s.score));}
            JSONObject result=empty("READY_EXTRACTIVE","Literal excerpts ranked by lexical similarity. Selection may omit important or opposing statements. All verified evidence windows are retained; no contradictions are resolved and no owners/dates/actions inferred.");result.put("excerpts",excerpts).put("evidenceCorpus",corpus).put("sentenceCount",size).put("omittedSentenceCount",size-selected.size()).put("coverage",size==selected.size()?"ALL_INPUT_SENTENCES":"SELECTED_EXCERPTS_ONLY").put("elapsedMs",SystemClock.elapsedRealtime()-begin).put("limits",new JSONObject().put("sourceChunks",32).put("windows",64).put("characters",16000).put("sentences",128).put("excerpts",8).put("rankingIterations",20).put("timeBudgetMs",timeBudgetMs));guard.check();return result;
        }catch(Stop stop){return empty(stop.status,stop.getMessage()).put("elapsedMs",SystemClock.elapsedRealtime()-begin);}catch(Exception error){return empty("Inspection window limit".equals(error.getMessage())?"RESOURCE_LIMIT":"INVALID_EVIDENCE",error.getClass().getSimpleName()+": "+error.getMessage()).put("elapsedMs",SystemClock.elapsedRealtime()-begin);}
    }
}
